#nullable enable

static class C
{
    static string M0(this string s, object x) => s;

    static void M1()
    {
        object x, y;
        _ = ""?.Equals(x = y = new object()) ?? false
            ? x.ToString()
            : y.ToString();
    }

    static void M2()
    {
        object w, x, y, z;
        _ = ""?.M0(w = x = new object())?.Equals(y = z = new object()) ?? false
            ? w.ToString() + y.ToString()
            : x.ToString() + z.ToString(); // 1
    }
}

